def weighted_distance(n, edges, start, finish):
    import heapq
    graph = [[] for _ in range(n)]
    for left, right, weight in edges:
        graph[left].append((right, weight))
        graph[right].append((left, weight))
    distance = [float('inf')] * n
    distance[start] = 0
    queue = [(0, start)]
    while queue:
        current, vertex = heapq.heappop(queue)
        if current != distance[vertex]:
            continue
        for neighbour, weight in graph[vertex]:
            candidate = current + weight
            if candidate < distance[neighbour]:
                distance[neighbour] = candidate
                heapq.heappush(queue, (candidate, neighbour))
    return -1 if distance[finish] == float('inf') else distance[finish]
